// Bis zu 5 freie Kennungen aus der Datenbank (Stefan 19.10.2026, BA2), je Kennung ein Eintrag für die Prüfung beim Chat-Server
const a = $input.first().json.a || {};
const k = Array.isArray(a.kandidaten) ? a.kandidaten.slice(0, 5) : [];
return k.map(kennung => ({ json: { auftrag_id: a.auftrag_id, kennung, adresse: a.adresse } }));

// Antworten von username_available auswerten (Stefan 19.10.2026, BA2): erste freie Kennung nehmen, belegte merken,
// bei 401/403, Zeitüberschreitung oder anderen Fehlern abbrechen (Fehlercode für die Datenbank)
const kand = $('Kandidaten').all();
const antw = $input.all();
const netz = (e) => {
  const t = typeof e === 'string' ? e : [e && e.message, e && e.description, e && e.code, e && e.name].filter(Boolean).join(' ');
  if (/credential/i.test(t)) return 'zugang';
  if (/timeout|timed out|ETIMEDOUT|ESOCKETTIMEDOUT|ECONNABORTED/i.test(t)) return 'zeitueberschreitung';
  if (/ECONNREFUSED|ENOTFOUND|EAI_AGAIN|EHOSTUNREACH|ENETUNREACH|ECONNRESET|socket hang up/i.test(t)) return 'verbindung';
  return 'server';
};
const lesen = (r) => {
  let b = r.data !== undefined ? r.data : r.body;
  if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { b = {}; } }
  return b && typeof b === 'object' ? b : {};
};
const einordnen = (r) => {
  if (r.error) return netz(r.error);
  const s = Number(r.statusCode) || 0;
  const b = lesen(r);
  if (s === 200 && b.available === true) return 'frei';
  if (s === 400 && (b.errcode === 'M_USER_IN_USE' || b.errcode === 'M_EXCLUSIVE')) return 'belegt';
  if (s === 400 && b.errcode === 'M_INVALID_USERNAME') return 'ungueltig:400';
  if (s === 401 || s === 403) return 'zugang:' + s;
  return 'server:' + s;
};
const belegt = [];
let frei = null;
let fehler = null;
for (let i = 0; i < kand.length; i++) {
  const code = einordnen((antw[i] && antw[i].json) || {});
  if (code === 'frei') { frei = kand[i].json.kennung; break; }
  if (code === 'belegt') { belegt.push(kand[i].json.kennung); continue; }
  fehler = code;
  break;
}
return [{ json: { auftrag_id: kand.length ? kand[0].json.auftrag_id : $('Auftrag holen').first().json.a.auftrag_id, kennung: frei, belegt, fehler: frei ? null : (fehler || 'belegt') } }];

// Antwort auf PUT /_synapse/admin/v2/users/<id> beim Anlegen (Stefan 19.10.2026, BA2): nur 201 (neu angelegt) gilt als Erfolg.
// 200 = gab es schon; Zeitüberschreitung oder 5xx = Ergebnis unklar (die Datenbank sperrt die Kennung dann vorsichtshalber).
const r = $input.first().json || {};
const ctx = $('Kennung festlegen').first().json;
let fehler = null;
if (r.error) {
  const e = r.error;
  const t = typeof e === 'string' ? e : [e.message, e.description, e.code, e.name].filter(Boolean).join(' ');
  if (/credential/i.test(t)) fehler = 'zugang';
  else if (/ECONNREFUSED|ENOTFOUND|EAI_AGAIN|EHOSTUNREACH|ENETUNREACH/i.test(t)) fehler = 'verbindung';
  else fehler = 'unklar';
} else {
  const s = Number(r.statusCode) || 0;
  if (s === 201) fehler = null;
  else if (s === 200) fehler = 'vorhanden:200';
  else if (s === 401 || s === 403) fehler = 'zugang:' + s;
  else if (s === 400) fehler = 'ungueltig:400';
  else if (s >= 500) fehler = 'unklar:' + s;
  else fehler = 'server:' + s;
}
return [{ json: { auftrag_id: ctx.auftrag_id, ok: fehler === null, fehler } }];

// Chat-Benutzer lesen vor Passwort bzw. Deaktivieren (Stefan 19.10.2026, BA2): PUT legt fehlende Benutzer sonst neu an.
// Das Passwort selbst wird hier nur auf Länge geprüft und nie weitergegeben.
const a = $('Auftrag holen').first().json.a;
const r = $input.first().json || {};
let weiter = false;
let ok = false;
let fehler = null;
if (r.error) {
  const e = r.error;
  const t = typeof e === 'string' ? e : [e.message, e.description, e.code, e.name].filter(Boolean).join(' ');
  if (/credential/i.test(t)) fehler = 'zugang';
  else if (/timeout|timed out|ETIMEDOUT|ESOCKETTIMEDOUT|ECONNABORTED/i.test(t)) fehler = 'zeitueberschreitung';
  else if (/ECONNREFUSED|ENOTFOUND|EAI_AGAIN|EHOSTUNREACH|ENETUNREACH|ECONNRESET|socket hang up/i.test(t)) fehler = 'verbindung';
  else fehler = 'server';
} else {
  const s = Number(r.statusCode) || 0;
  let b = r.data !== undefined ? r.data : r.body;
  if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { b = {}; } }
  b = b && typeof b === 'object' ? b : {};
  if (s === 200) {
    if (a.art === 'deaktivieren') {
      if (b.deactivated === true) ok = true; else weiter = true;
    } else if (b.deactivated === true) {
      fehler = 'deaktiviert';
    } else {
      const pw = $('Start').first().json.passwort;
      const n = typeof pw === 'string' ? pw.length : 0;
      if (n < 10 || n > 512) fehler = 'passwort'; else weiter = true;
    }
  } else if (s === 404) fehler = 'fehlt:404';
  else if (s === 401 || s === 403) fehler = 'zugang:' + s;
  else fehler = 'server:' + s;
}
return [{ json: { auftrag_id: a.auftrag_id, art: a.art, adresse: a.adresse, matrix_user_id: a.matrix_user_id, weiter, ok, fehler } }];

// Antwort auf PUT /_synapse/admin/v2/users/<id> beim Passwort bzw. Deaktivieren (Stefan 19.10.2026, BA2): 200 = erledigt
const r = $input.first().json || {};
const ctx = $('Lesen auswerten').first().json;
let fehler = null;
if (r.error) {
  const e = r.error;
  const t = typeof e === 'string' ? e : [e.message, e.description, e.code, e.name].filter(Boolean).join(' ');
  if (/credential/i.test(t)) fehler = 'zugang';
  else if (/ECONNREFUSED|ENOTFOUND|EAI_AGAIN|EHOSTUNREACH|ENETUNREACH/i.test(t)) fehler = 'verbindung';
  else fehler = 'zeitueberschreitung';
} else {
  const s = Number(r.statusCode) || 0;
  if (s === 200) fehler = null;
  else if (s === 401 || s === 403) fehler = 'zugang:' + s;
  else if (s === 404) fehler = 'fehlt:404';
  else if (s === 400 && ctx.art === 'passwort') fehler = 'passwort:400';
  else fehler = 'server:' + s;
}
return [{ json: { auftrag_id: ctx.auftrag_id, ok: fehler === null, fehler } }];

// Rückgabe an den aufrufenden Ablauf (Stefan 19.10.2026, BA2): Ergebnis aus der Datenbank, ohne Passwort
const j = $input.first().json || {};
const r = j.ergebnis || j.a || {};
return [{ json: { ok: r.ok === true, auftrag_id: r.auftrag_id ?? null, art: r.art ?? null, kennung: r.kennung ?? null,
  matrix_user_id: r.matrix_user_id ?? null, fehler: r.fehler ?? null, meldung: r.meldung ?? null } }];
